function audioCheck(){$('panel').scrollTop=0;stopAudio();overlay='audio-check';const e=list().find(e=>e.id==='water'&&hasVoice(e))||list().find(hasVoice);$('panel').innerHTML='<h1>Проверка звука</h1><p id="check-word"></p><audio id="native-audio-check" controls playsinline preload="auto" style="width:100%"></audio><p id="audio-check-status" role="status">Ожидаем нажатия.</p><p>Если плеер идёт, но тишина: увеличь громкость мультимедиа и проверь, не подключены ли Bluetooth-наушники.</p><div id="audio-back" class="actions"></div>';const a=$('native-audio-check');$('check-word').textContent=e?languageName()+': '+e.text+' — '+e.name+(e.syntheticAudio?' · синтетический голос':'')+'. Нажми ▶ в плеере.':languageName()+': для этого языка пока нет записи.';a.hidden=!e;if(e)a.src=(e.publicRecording||e.syntheticAudio).src;a.onplay=()=>stopAudio(false);a.onplaying=()=>{$('audio-check-status').textContent='Запись воспроизводится · '+(a.muted?'звук выключен':'громкость '+Math.round(a.volume*100)+'%')};a.onended=()=>{$('audio-check-status').textContent='Запись закончилась. Если её не слышно, звук не доходит до динамика.'};a.onerror=()=>{$('audio-check-status').textContent='Ошибка плеера: '+a.error?.code};$('audio-back').append(button('Вернуться к игре',()=>{a.pause();resume()},'primary'),button('В меню',()=>{a.pause();menu()}))}
function playRecording(src,onBlocked){const serial=++playSerial;audio=audioPlayer;audioPlayer.muted=false;audioPlayer.volume=1;audioPlayer.src=src;audioPlayer.play().catch(async error=>{if(serial!==playSerial)return;try{if(!audioContext)throw error;await audioContext.resume();if(audioContext.state!=='running')throw error;let buffer=decodedClips.get(src);if(!buffer){const response=await fetch(src);if(!response.ok)throw new Error('audio');buffer=await audioContext.decodeAudioData(await response.arrayBuffer());decodedClips.set(src,buffer)}if(serial!==playSerial)return;bufferSource=audioContext.createBufferSource();bufferSource.buffer=buffer;bufferSource.connect(audioContext.destination);bufferSource.onended=()=>{if(serial===playSerial)bufferSource=null};bufferSource.start();$('audio-toggle').dataset.playback='webaudio';$('audio-toggle').textContent='🔊'}catch{if(serial!==playSerial)return;$('audio-toggle').textContent='🔇';$('audio-toggle').setAttribute('aria-label','Нажми, чтобы включить звук');$('tip').textContent='Нажми 🔇 сверху, чтобы включить звук.';onBlocked?.()}})}
