function migrateRewards(){if(s.economy.answerReward===5)return;s.economy={balance:s.economy.balance+(styleCount()-s.economy.answers)*3+(s.coinKeys.length-s.economy.coins)-s.economy.spent,answers:styleCount(),coins:s.coinKeys.length,spent:0,answerReward:5}}
function points(){return s.economy.balance+(styleCount()-s.economy.answers)*5+(s.coinKeys.length-s.economy.coins)-s.economy.spent}
function hasHome(){return houses.some(h=>(s.buildings[h.id]||0)>=h.stages)}
function house(){return houses.find(h=>h.id===s.houseChoice)||houses[0]}
const estatePages=[{name:'Дом',goal:'Первый дом',house:'cottage',items:['flowers','lanterns','fence','jug','grapes']},{name:'Сад',goal:'Дом с садом',house:'stone',items:['tree','fountain','gazebo','swing','rainbow','bridge','lamb']},{name:'Горный участок',goal:'Большой горный дом',house:'tower',items:['well','table','chair','night','campfire']}];
function estatePage(){return Math.max(0,houses.findIndex(h=>h.id===s.houseChoice))}
function onEstatePage(id){return estatePages[estatePage()].items.includes(id)}
function setupEstatePages(){const tabs=$('estate-pages');if(!tabs)return;tabs.replaceChildren();estatePages.forEach((page,i)=>{const owned=(s.buildings[page.house]||0)>=houses[i].stages;const b=button((i+1)+'. '+page.name+(owned?' ✓':''),()=>{s.houseChoice=page.house;s.estateWalk={...walkDoor(),inside:false};arranging=false;selectedDecor=null;save();if(overlay==='home')myHome();else if(overlay==='finish')showFinish();else shop()},i===estatePage()?'chosen':'');b.setAttribute('aria-pressed',String(i===estatePage()));tabs.append(b)});const h=house(),owned=(s.buildings[h.id]||0)>=h.stages,remaining=Math.max(0,h.total-points());$('estate-goal').textContent=owned?'Дом куплен! Обустраивай этот участок или собирай на следующую страницу.':estatePages[estatePage()].goal+' · '+h.total.toLocaleString('ru-RU')+' ⭐ · осталось '+remaining.toLocaleString('ru-RU')+' ⭐';$('estate-progress').max=h.total;$('estate-progress').value=owned?h.total:Math.max(0,points())}
function homeGoal(){const h=house();return (s.buildings[h.id]||0)>=h.stages?'🏠 '+h.name+' · твой участок':'Пустой участок · '+h.name+' за '+h.total.toLocaleString('ru-RU')+' ⭐'}
