 if($('night-toggle')){$('night-toggle').hidden=!s.purchases.includes('night');$('night-toggle').textContent=isNight()?'☀️ Включить день':'🌙 Включить ночь';$('night-toggle').onclick=toggleNight}
 const goods=$('plotgoods'),extras=$('extragoods');if(!goods||!extras)return;goods.replaceChildren();extras.replaceChildren();
