// Validate a transfer before it can replace any existing player's progress.
function validateSave(data){
 const record=v=>v!==null&&typeof v==='object'&&!Array.isArray(v);
 const nonnegative=v=>Number.isSafeInteger(v)&&v>=0;
 const strings=v=>Array.isArray(v)&&v.every(x=>typeof x==='string');
 const required=ok=>{if(!ok)throw Error('invalid-save')};
 const languages=['kbd','krc','ce','os','ab','abq','av'];
 required(record(data)&&data.version===2&&languages.includes(data.lang)&&record(data.players)&&typeof data.active==='string'&&Object.hasOwn(data.players,data.active));
 for(const p of Object.values(data.players)){
  required(record(p)&&typeof p.name==='string'&&record(p.modes));
  if(p.ageBand!==undefined)required(['under8','8plus'].includes(p.ageBand));
  for(const [lang,m] of Object.entries(p.modes)){
   required(languages.includes(lang)&&record(m)&&nonnegative(m.level)&&nonnegative(m.gate)&&m.gate<=3&&['run','gate','finish','dead'].includes(m.phase));
   required((m.phase!=='gate'||m.gate<3)&&(m.phase!=='finish'||m.gate===3));
   required(['x','y','vy'].every(k=>Number.isFinite(m[k]))&&strings(m.coinKeys)&&strings(m.purchases)&&strings(m.known)&&strings(m.review));
   required(Array.isArray(m.rewards)&&m.rewards.every(nonnegative)&&record(m.economy)&&['balance','answers','coins','spent'].every(k=>Number.isFinite(m.economy[k])&&m.economy[k]>=0));
   if(m.tokens===undefined)m.tokens=[];
   required(Array.isArray(m.tokens)&&m.tokens.every(nonnegative));
   if(m.question!==null&&m.question!==undefined)required(record(m.question)&&typeof m.question.id==='string'&&['learn','test'].includes(m.question.stage)&&nonnegative(m.question.mistakes));
   for(const key of ['nextCard','attemptCard'])if(m[key]!==undefined)required(nonnegative(m[key]));
   if(m.worldTime!==undefined)required(Number.isFinite(m.worldTime)&&m.worldTime>=0);
   for(const key of ['creditedGates','hiddenDecor'])if(m[key]!==undefined)required(strings(m[key]));
   if(m.defeatedMonsters!==undefined)required(Array.isArray(m.defeatedMonsters)&&m.defeatedMonsters.every(nonnegative));
   if(m.buildings!==undefined)required(record(m.buildings)&&Object.entries(m.buildings).every(([id,stage])=>houses.some(h=>h.id===id&&nonnegative(stage)&&stage<=h.stages)));
   if(m.houseChoice!==undefined)required(houses.some(h=>h.id===m.houseChoice));
   if(m.decorPositions!==undefined)required(record(m.decorPositions)&&Object.values(m.decorPositions).every(pos=>record(pos)&&Number.isFinite(pos.x)&&Number.isFinite(pos.y)));
   if(m.estateWalk!==undefined)required(record(m.estateWalk)&&Number.isFinite(m.estateWalk.x)&&typeof m.estateWalk.inside==='boolean'&&(m.estateWalk.y===undefined||Number.isFinite(m.estateWalk.y)));
  }
 }
}
function playersMenu(){$('panel').scrollTop=0;stopVoice();stopAudio();overlay='players';$('panel').innerHTML='<h1>Кто играет?</h1><div id="players" class="actions"></div><label>Имя нового игрока<input id="playername" maxlength="30" placeholder="Например, Айрат"></label><div id="playeractions" class="actions"></div><p class="muted">У каждого свои звёзды, дом и история. Сохраняются на этом устройстве и в этом браузере. Для переноса скачай сохранение и загрузи его в другой копии игры.</p><div id="transfer" class="actions"></div><input type="file" id="restore" accept="application/json,.json" hidden><p id="transferstatus"></p><div id="back"></div>';for(const [id,p] of Object.entries(store.players))$('players').append(button(p.name+(id===store.active?' ✓':''),()=>{save();store.active=id;lastSpoken=null;load();menu()},id===store.active?'chosen':''));$('playeractions').append(button('Добавить игрока',()=>{const name=$('playername').value.trim();if(!name)return;const id=crypto.randomUUID?crypto.randomUUID():'p'+Date.now();store.players[id]={name,modes:{}};store.active=id;load();menu()},'primary'));$('transfer').append(button('↓ Скачать сохранение',()=>{save();const blob=new Blob([JSON.stringify(store)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lumi-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}),button('↑ Загрузить сохранение',()=>$('restore').click()));$('restore').onchange=async()=>{try{const data=JSON.parse(await $('restore').files[0].text());validateSave(data);const previous=store;store=data;try{lastSpoken=null;stopAudio();load();menu()}catch(error){store=previous;load();playersMenu();throw error}}catch{$('transferstatus').textContent='Не удалось открыть сохранение Луми.'}};$('back').append(button('В меню',menu))}

function outfitName(n){return n<=8?wardrobe[n-1]:'Новый цвет наряда № '+(n-8)}
function answer(correct){if(!s.question||!['gate','run'].includes(s.phase)||s.question.stage!=='test')return;let e=card();if(!correct){s.question.mistakes++;s.tokens=[];if(!s.review.includes(e.id))s.review.push(e.id);save();showQuestion();$('feedback').textContent='Попробуй ещё. Подсказка поможет!';return}if(!s.known.includes(e.id))s.known.push(e.id);if(s.question.mistakes===0)s.review=s.review.filter(id=>id!==e.id);if(!s.question.isReview)s.nextCard++;stopVoice();$('word-preview').hidden=true;const creditKey=s.level+':'+s.gate,alreadyCredited=s.creditedGates.includes(creditKey);if(alreadyCredited)s.economy.spent+=5;else s.creditedGates.push(creditKey);s.gate++;s.phase='run';s.question=null;s.tokens=[];overlay='';$('panel').innerHTML='';$('tip').textContent=(alreadyCredited?'Ворота открыты · ':'⭐ +5 звёзд · ')+outfitName(styleCount());save();announce(C[store.lang].find(e=>e.id==='thanks'))}
function reward(){s.phase='finish';if(!s.rewards.includes(s.level))s.rewards.push(s.level);save();showFinish()}
function nextRoute(){resetEncounters();s.level++;s.defeatedMonsters=[];s.attemptCard=s.nextCard;route=LumiWorld.make(s.level);s.worldTime=0;s.x=40;s.y=420;s.vy=0;s.gate=0;s.phase='run';s.question=null;s.tokens=[];overlay='';$('panel').innerHTML='';save();announce(eventPhrases[0])}
function showFinish(){overlay='finish';stopAudio();$('panel').innerHTML=`<div class="finish-heading"><h1>Прошли уровень!</h1></div><div class="actions finish-actions" id="next"></div>${estateMarkup().split('<p class="estate-balance">')[0]}<details class="finish-stats"><summary>Итоги маршрута</summary><p>⭐ Звёзд: ${points()} · 🪙 Монет за маршрут: ${s.coinKeys.filter(k=>k.startsWith(s.level+':')).length}</p><p>${homeGoal()}</p><p>Деталей образа: ${styleCount()} · Подарков: ${s.rewards.length} · Знакомых карточек: ${s.known.length}</p></details>`;$('next').append(button('🚶 Гулять у дома',walkHome,'primary'),button('⭐ Потратить очки',shop),button('Мой дом и сад',myHome),button('В сад и меню',menu),button('Следующий маршрут →',nextRoute,'primary'));paintEstate();$('panel').scrollTop=0;announce(eventPhrases[1]);$('spoken')?.remove()}

