 $('start').append(button(s.phase==='dead'?'Повторить испытание':s.phase==='finish'?'Посмотреть подарок':s.phase==='gate'?'Вернуться к воротам':'В путь →',resume,'primary'));
 if(list().some(e=>e.kind==='phrase'))$('storefront').append(button('Фразы · словарь',phraseBook));
