function resume(){if(s.phase==='dead'){showDefeat();return}if(s.phase==='gate'){showQuestion();speak()}else if(s.phase==='finish')showFinish();else{overlay='';$('panel').innerHTML='';if(s.tour)announce(eventPhrases[0]);if(!s.tour){overlay='tutorial';$('panel').innerHTML='<div class="big">↟</div><h2>Один прыжок</h2><p>Луми идёт вправо сам. Нажми большую жёлтую кнопку, чтобы перепрыгнуть ступеньку.</p><div id="go"></div>';$('go').append(button('Понятно · идём!',()=>{s.tour=true;overlay='';$('panel').innerHTML='';save();announce(eventPhrases[0])},'primary'))}}}
function pause(){if(overlay==='pause'){resume();return}if(overlay)return;overlay='pause';stopVoice();$('word-preview').hidden=true;stopAudio();save();$('panel').innerHTML='<div class="big">☁️</div><h2>Передышка</h2><p>Мир и вопрос сохранены.</p><div id="go"></div>';$('go').append(button('Продолжить',resume,'primary'),button('Маршрут и язык',menu))}
function previewWord(){if(!s.question){s.question=question();s.question.preview=true;save();if(hasVoice(card()))speak()}const e=card(),box=$('word-preview');box.hidden=false;bilingual(box,e.icon+' '+e.text,e.name);if(voiceEnabled&&voiceReady&&!recognizer&&(!audio||audio.paused))listenAnswer()}
async function enableVoice(){stopVoice();const mode=store.lang,info=$('voice-info');info.textContent='Проверяю языковой пакет…';const result=await LumiVoice.availability(mode);if(mode!==store.lang||!info.isConnected)return;voiceReady=result.ok;voiceEnabled=result.ok;info.textContent=result.reason;if(result.ok)info.textContent='Ответ голосом включён: нажми «В путь», скажи слово до ворот. Это эксперимент, не оценка произношения.'}
function stopVoice(){if(recognizer){const r=recognizer;recognizer=null;r.onresult=null;r.onend=null;try{r.abort()}catch{}}}
function listenAnswer(){if(!voiceEnabled||!voiceReady||overlay||!s.question)return;const R=window.SpeechRecognition||window.webkitSpeechRecognition,r=new R(),id=s.question.id,level=s.level,gate=s.gate;recognizer=r;r.lang=store.lang;r.processLocally=true;r.interimResults=false;r.continuous=false;r.onresult=e=>{if(overlay||s.level!==level||s.gate!==gate||!s.question||s.question.id!==id)return;const result=e.results[0];if(result.isFinal&&result[0].confidence>=.7&&LumiVoice.normalize(result[0].transcript)===LumiVoice.normalize(card().text)){s.question.stage='test';answer(true)}};r.onerror=()=>{voiceEnabled=false;stopVoice();$('tip').textContent='Голос недоступен. У ворот выбери ответ.'};r.onend=()=>{if(recognizer===r)recognizer=null};try{stopAudio();r.start()}catch{voiceEnabled=false;stopVoice()}}
function loseAttempt(reason){stopVoice();stopAudio();s.phase='dead';s.deathReason=reason;s.vy=0;save();showDefeat()}
function showDefeat(){$('panel').scrollTop=0;overlay='defeat';$('word-preview').hidden=true;$('panel').innerHTML='<div class="big">💫</div><h1>Луми погиб</h1><p>'+escapeText(s.deathReason||'Столкновение с великаном.')+'</p><p>Маршрут не пройден. Перепрыгни великана и попробуй ещё раз.</p><div id="retry" class="actions"></div>';$('retry').append(button('↻ Начать маршрут заново',retryRoute,'primary'),button('Мой дом и сад',myHome),button('В меню',menu))}
function retryRoute(){resetEncounters();const balance=points();s.defeatedMonsters=[];s.gate=0;s.nextCard=s.attemptCard;s.question=null;s.tokens=[];s.x=40;s.y=route.floor(40);s.vy=0;s.worldTime=0;s.phase='run';s.economy={balance,answers:s.level*3,coins:s.coinKeys.length,spent:0,answerReward:5};overlay='';$('panel').innerHTML='';$('tip').textContent='↟ Перепрыгни одноглазого великана. Звёзды за повтор уже открытых ворот не начисляются.';save()}
function drawMonster(x,y){ctx.save();ctx.translate(x,y);ctx.fillStyle='#564077';ctx.beginPath();ctx.ellipse(0,-27,23,28,0,0,7);ctx.fill();ctx.fillStyle='#3b2d58';ctx.fillRect(-20,-6,14,8);ctx.fillRect(6,-6,14,8);ctx.fillStyle='#fff4d8';ctx.beginPath();ctx.ellipse(0,-36,13,12,0,0,7);ctx.fill();ctx.fillStyle='#362c47';ctx.beginPath();ctx.arc(Math.sin(s.worldTime)*2,-35,5,0,7);ctx.fill();ctx.strokeStyle='#bba0d5';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-18,7,0,Math.PI);ctx.stroke();ctx.restore()}

function jump(){if(overlay||s.phase!=='run'||s.vy<0)return;const floor=route.platforms.find(([x,w,y])=>s.x+15>x&&s.x-15<x+w&&Math.abs(s.y-y)<2);if(floor){s.vy=-610;encounter('lumi-jump','jump-'+s.worldTime);save()}}
function critterX(c){return c.x+Math.sin(s.worldTime*(c.speed||1.1)+c.id)*c.range}
function step(dt){if(overlay||s.phase!=='run')return;if(dt>1/60){const steps=Math.ceil(dt*60);for(let i=0;i<steps;i++)step(dt/steps);return}encounter();s.worldTime+=dt;let oldY=s.y;s.vy+=1400*dt;s.y+=s.vy*dt;let next=s.x+112*dt;const wall=route.platforms.find(([x,w,y])=>s.x+15<=x&&next+15>x&&s.y>y+3);let blocked=!!wall;
for(const c of route.critters){const x=critterX(c);if(s.x<x&&next+16>x-18&&s.y>route.floor(x)-36){blocked=true;$('tip').textContent='Зверёк на тропе — перепрыгни ↟';if(route.theme.critter==='🦔')encounter('hedgehog-pass','hedgehog-'+c.id)}}
for(const m of route.monsters){if(s.defeatedMonsters.includes(m.id))continue;const mx=critterX(m),my=route.floor(mx),top=my-54,overlap=next+10>mx-17&&s.x-10<mx+17;if(mx-s.x>70&&mx-s.x<250)encounter('monster-come','monster-first');if(overlap&&s.vy>0&&oldY<my-6&&s.y>=top-6){s.defeatedMonsters.push(m.id);s.y=top;s.vy=-380;$('tip').textContent='✨ Прыжок сверху — великан побеждён!';encounter('monster-defeated','monster-defeated-'+m.id,true);save();continue}if(overlap&&oldY>=my-6&&s.y>my-6&&s.vy>=0){loseAttempt('Луми столкнулся с одноглазым великаном.');return}}if(!blocked)s.x=next;else if(wall)$('tip').textContent='Ступенька впереди — нажми ↟ Прыжок';if(s.vy>=0)for(const[x,w,y]of route.platforms)if(s.x+14>x&&s.x-14<x+w&&oldY<=y&&s.y>=y){s.y=y;s.vy=0;break}
if(s.y>650){loseAttempt('Луми упал с горной тропы.');return}
for(const c of route.coins){const key=s.level+':'+c.id;if(!s.coinKeys.includes(key)&&Math.abs(s.x-c.x)<30&&Math.abs(s.y-45-c.y)<52){s.coinKeys.push(key);$('tip').textContent='🪙 +1 очко на свой дом!';save()}}
if(s.gate<3){if(s.x>=gateX()-350)previewWord();if(s.x>=gateX()-38)openGate()}
if(s.gate===3&&s.x>=route.finish)reward()}
