if(n>=4){ctx.fillStyle='#463529';ctx.fillRect(-18,-22,36,5);ctx.fillStyle='#dcc18a';ctx.fillRect(-2,-23,6,7)}
if(n>=5){ctx.strokeStyle='#d4b775';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-17,-40);ctx.lineTo(-19,-7);ctx.moveTo(17,-40);ctx.lineTo(19,-7);ctx.stroke()}
