if(n>=8){ctx.strokeStyle='#e1bf77';ctx.lineWidth=1.5;for(const side of [-1,1])for(let j=0;j<3;j++){let px=side*12,py=-15+j*3;ctx.beginPath();ctx.moveTo(px-2,py);ctx.lineTo(px,py-2);ctx.lineTo(px+2,py);ctx.stroke()}}
if(n<6){ctx.fillStyle='#ea8660';ctx.beginPath();ctx.moveTo(-18,-40);ctx.lineTo(-43,-31+Math.sin(s.x/18)*5);ctx.lineTo(-19,-27);ctx.fill()}
