ctx.fillStyle=theme.cloud;for(let i=0;i<5;i++){let x=i*160-(cam*.12%160);if(s.level%5===1){ctx.font='22px system-ui';ctx.fillText('✦',x,130+i%2*60)}else{ctx.beginPath();ctx.ellipse(x,150+i%2*65,50,15,0,0,7);ctx.fill()}}
ctx.translate(-cam,0);for(const[x,w,y]of route.platforms){ctx.fillStyle=theme.earth;ctx.fillRect(x,y,w,200);ctx.fillStyle=theme.grass;ctx.fillRect(x,y,w,10);ctx.fillStyle=theme.hill;for(let j=20;j<w;j+=44)ctx.fillRect(x+j,y+30,14,5)}
