ctx.font='37px system-ui';for(const c of route.critters){const x=critterX(c),y=route.floor(x);ctx.fillText(theme.critter,x-19,y-2);const id={'🐑':'caucasus-lamb','🐸':'caucasus-frog','🦊':'caucasus-fox','🦔':'caucasus-hedgehog'}[theme.critter],word=overlay!=='menu'&&list().find(e=>e.id===id);if(word){ctx.save();ctx.textAlign='center';ctx.fillStyle='#173d45';ctx.font='bold 14px system-ui';ctx.fillText(word.text,x,y-65);ctx.font='10px system-ui';ctx.fillText(word.name,x,y-51);ctx.restore();ctx.font='37px system-ui'}}
