function footerAction(){if(!overlay&&s.phase==='run')return jump();if(s.phase==='finish')return nextRoute();resume()}
function updateFooter(){const mode=overlay==='menu'?'welcome':!overlay&&s.phase==='run'?'jump':s.phase==='finish'?'next':'go',b=$('jump');if(b.dataset.action===mode)return;b.dataset.action=mode;b.replaceChildren();const label=document.createElement('span');label.textContent=mode==='jump'?'↟':mode==='next'?'Следующий маршрут →':'В путь →';b.append(label);if(mode==='jump'){const sub=document.createElement('small');sub.textContent='Прыжок';b.append(sub)}b.setAttribute('aria-label',mode==='jump'?'Прыжок':label.textContent)}
function bilingual(el,main,translation){el.replaceChildren();const text=document.createElement('span'),sub=document.createElement('small');text.textContent=main;sub.textContent=translation;sub.className='translation';el.append(text,sub)}
function frame(t){let dt=Math.min((t-last)/1000||0,.033);last=t;updateFooter();if(overlay==='walk')stepWalk(dt);else if(['home','shop','finish'].includes(overlay)&&['fountain','campfire'].some(id=>s.purchases.includes(id)&&!decorHidden(id)&&onEstatePage(id)))paintEstate(true);step(dt);draw();if(t-saveTime>350){save();saveTime=t}requestAnimationFrame(frame)}
$('audio-toggle').onclick=()=>{if(!list().some(hasVoice)){$('tip').textContent=languageName()+' пока без голоса';return}if(overlay==='menu'){audioCheck();return}if(overlay==='audio-check'){repeatAudioCheck();return}if(overlay==='phrases'&&lastSpoken){announce(lastSpoken);return}if(s.question)speak();else if(store.lang==='kbd')announce(lastSpoken||eventPhrases[0]);else{stopAudio();const e=lastSpoken||list().find(hasVoice);lastSpoken=e;playRecording((e.publicRecording||e.syntheticAudio).src)}};$('jump').onclick=e=>{if(e.detail===0)footerAction()};$('jump').onpointerdown=e=>{e.preventDefault();footerAction()};$('pause').onclick=pause;$('menu').onclick=menu;document.addEventListener('keyup',e=>{if(e.code==='ArrowLeft'||e.code==='ArrowRight')walkDirection=0});window.addEventListener('blur',()=>{walkDirection=0;walkTarget=null});document.addEventListener('keydown',e=>{if(overlay==='walk'&&['ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();walkDirection=e.code==='ArrowLeft'?-1:1;walkTarget=null;return}if(overlay==='walk'&&e.code==='Enter'){e.preventDefault();$('walkdoor').click();return}if(e.code==='Space'&&!overlay){e.preventDefault();jump()}if(e.code==='Escape')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){if(!overlay)pause();stopAudio();save()}});window.addEventListener('pagehide',()=>{stopVoice();save()});load();menu();requestAnimationFrame(frame);
